    s = p.read_text()
    for m in re.finditer(r'CREATE TABLE (?:IF NOT EXISTS )?(?:public\.)?(\w+)\s*\(', s):
        t = m.group(1); depth = 1; i = m.end()
        while i < len(s) and depth:
            if s[i] == '(': depth += 1
            elif s[i] == ')': depth -= 1
            i += 1
        body = re.sub(r'--[^\n]*', '', s[m.end():i-1])
        cols.setdefault(t, set()).update(cm.group(1) for cm in re.finditer(r'(?:^|,)\s*(\w+)\s+[a-zA-Z]', body))

